private actor TaskActionGate {
    private var waiting:CheckedContinuation<Void,Never>?
    private var started=false
    func pause() async {started=true;await withCheckedContinuation{waiting=$0}}
    func waitForStart() async throws {for _ in 0..<2000 {if started{return};try await Task.sleep(nanoseconds:1_000_000)};throw TaskActionMatrix.Failure(description:"Fixture gate did not start")}
    func release(){waiting?.resume();waiting=nil}
}
/// Named offline authority fixture. It is neither EventKit nor a production approval service.
private actor TaskActionFixtureBackend:ConversationTaskActionBackend {
    enum Mode {case accepted,unknown,notFound,conflict,notSent,invalidReceipt}
    var snapshot:ConversationTaskActionSnapshot
    var mode:Mode
    var available=true
    var posts:[ConversationTaskActionDecisionRequest]=[]
    var reads:[UUID]=[]
    var gate:TaskActionGate?
    var receipts:[UUID:ConversationTaskActionEnvelope]=[:]
    init(snapshot:ConversationTaskActionSnapshot,mode:Mode = .accepted){self.snapshot=snapshot;self.mode=mode}
    func configure(available:Bool?=nil,gate:TaskActionGate?=nil){if let available{self.available=available};self.gate=gate}
    func replace(_ value:ConversationTaskActionSnapshot){snapshot=value}
    func counts()->([UUID],[UUID]){(posts.map(\.operationID),reads)}
    func decisionAvailability(_ reference:ConversationTaskActionReference) async throws -> Bool {available}
    func readActions(_ reference:ConversationTaskActionReference) async throws -> ConversationTaskActionCatalog {.init(reference:reference,actions:[snapshot])}
    func readAction(_ reference:ConversationTaskActionReference,actionID:String) async throws -> ConversationTaskActionEnvelope {.init(action:snapshot)}
    func decideAction(_ reference:ConversationTaskActionReference,actionID:String,request:ConversationTaskActionDecisionRequest) async throws -> ConversationTaskActionEnvelope {
        if mode == .notSent {throw ConversationTaskActionDispatchFailure.notSent}
        posts.append(request)
        if mode == .conflict {throw catError.conflict}
        snapshot.revision += 1;snapshot.approval_status=request.decision == .approve ? "approved":"denied";snapshot.decision_operation_id=request.operationID.uuidString.lowercased();snapshot.effect = .init(status:request.decision == .approve ? "waiting_device":"not_dispatched")
        let receipt=ConversationTaskActionDecisionReceipt(operation_id:request.operationID.uuidString.lowercased(),action_id:actionID,decision:request.decision,action_digest:request.action_digest,committed_at:"2026-10-14T00:05:00.000Z")
        var envelope=ConversationTaskActionEnvelope(action:snapshot,decision:receipt)
        if mode == .invalidReceipt {envelope.decision?.action_digest=String(repeating:"b",count:64)}
        receipts[request.operationID]=envelope
        if let gate {await gate.pause()}
        if mode == .unknown || mode == .notFound {throw catError.unavailable("Named synthetic lost response")}
        return envelope
    }
    func readDecision(_ reference:ConversationTaskActionReference,actionID:String,operationID:UUID) async throws -> ConversationTaskActionEnvelope {
        reads.append(operationID)
        if mode == .notFound {throw ConversationTaskActionError.originalNotFound}
        guard var receipt=receipts[operationID] else {throw ConversationTaskActionError.originalNotFound};receipt.action=snapshot;return receipt
    }
}
private final class TaskActionFailingPersistence:SnapshotPersistence,@unchecked Sendable {
    let base:FilePersistence
    private let lock=NSLock();private var fails=false
    init(url:URL){base=FilePersistence(url:url)}
    func failNext(){lock.lock();fails=true;lock.unlock()}
    func load() throws -> StoreSnapshot {try base.load()}
    func save(_ value:StoreSnapshot) throws {lock.lock();let fail=fails;fails=false;lock.unlock();if fail {throw catError.unavailable("Named synthetic disk failure")};try base.save(value)}
}
